"""Recoverable trusted-editor HTML projection, no remote requests."""
import html
import json
from pathlib import Path
from .attention_summary import summarize
from .attention_summary_view import render_summary
from .attention_positions import project_positions


def render(state, session=None):
    data = json.dumps(state, ensure_ascii=True).replace('<', '\\u003c')
    summary = summarize(state)
    saved = json.dumps(summary, ensure_ascii=True).replace('<', '\\u003c')
    positions = json.dumps(project_positions(summary), ensure_ascii=True).replace('<', '\\u003c')
    map_script = Path(__file__).with_name('attention_map.js').read_text(encoding='utf-8')
    position_script = Path(__file__).with_name('attention_positions.js').read_text(encoding='utf-8')
    views = Path(__file__).with_name('attention_views.js').read_text(encoding='utf-8')
    script = Path(__file__).with_name('attention_editor.js').read_text(encoding='utf-8')
    page = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; connect-src 'none'"><title>B关注分析</title><style></style><body><header><h1>评语分析</h1><p id="revision"></p><p id="material"></p><p id="page-draft" role="status"></p><nav aria-label="结果页导航"><a href="#attention-editor">材料</a><a href="#focus-shell" aria-current="page">结果</a><a href="#view-overview">查看统计</a></nav></header>
<section aria-label="保存结果与筛选" id="attention-views"><h2>B关注什么，与A如何对应</h2><p id="view-version"></p><p id="view-hits" role="status"></p><details id="reading-details"><summary>逐项证据与关系明细</summary><div id="view-detail"></div></details><details id="view-options"><summary>更多查看方式</summary><details id="view-filters"><summary>筛选记录与表达</summary><div id="view-controls"></div></details><details id="view-statistics"><summary>主题与统计</summary><p>按记录去重，各项可重叠；数字只描述本批表达。统计属于已保存修订，下载修改文件不会更新。</p><div id="view-summary">''' + render_summary(summary) + '''</div></details><div id="view-positions"></div><details id="view-extra-views"><summary>更多图表：矩阵与关系图</summary><label><input type="checkbox" id="view-matrix-toggle"> 显示记录×主题/A矩阵</label><div id="view-matrix" hidden></div><label><input type="checkbox" id="view-graph-toggle"> 显示局部关系图</label><div id="view-graph" hidden></div></details></details></section><details id="attention-editor"><summary>查看原话与修改</summary><p>修改后下载修改文件，回本机窗口保存，再重开查看。此处可查全部材料，不随上方筛选隐藏。</p><section><h2>原话与原分</h2><label>评语记录<select id="record"></select></label><label>原话位置<select id="section"></select></label><details id="editor-source-position"><summary>来源位置</summary><p id="locator"></p></details><pre id="source" tabindex="0"></pre><div id="scores"></div><p id="record-note"></p></section>
<section><h2>观点与方面</h2><label>观点<select id="opinion"></select></label><label>观点方面<select id="facet"></select></label><details id="editor-structure"><summary>拆分或合并观点</summary><p>拆合后需重新核对主题与A对应，旧解释保留在历史中。</p><button id="split" type="button">按方面拆分观点</button><label>选择同记录观点归并<select id="merge-opinions" multiple size="4"></select></label><button id="merge" type="button">归并所选观点</button></details><p>选取原话作为依据，再填写解释。</p><button id="capture" type="button">采用选中文字</button><label>原话片段<select id="passage"></select></label><p id="evidence"></p><button id="evidence-add" type="button">追加为本方面证据</button><p id="facet-evidence-list"></p><label>分析解释<textarea id="interpretation"></textarea></label><details id="editor-analysis-details"><summary>分析类型与核对状态</summary><label>方面类型<select id="facet-kind"><option value="content">内容关注</option><option value="disposition">流程或总体处置</option></select></label><label>核对状态<select id="status"><option value="working">未核对</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label>
</details><details id="editor-expression"><summary>补充条件、理由与表达方式</summary><label>对象<input id="object"></label><label>判断方向<input id="direction"></label><label>程度<input id="degree"></label><label>否定<input id="negation"></label><label>理由<textarea id="reasons"></textarea></label><label>条件<textarea id="conditions"></textarea></label><label>动作<textarea id="actions"></textarea></label><label>例示<textarea id="examples"></textarea></label><label>备选<textarea id="alternatives"></textarea></label><label>本次表达作用<textarea id="function"></textarea></label><label>套话候选<select id="boilerplate"><option value="unknown">未判断</option><option value="true">是候选</option><option value="false">非候选</option></select></label></details>
<details id="editor-a-links"><summary>修改与A的对应</summary><p>同一方面可保留多个对应、清单外及未定范围。先将方面暂存修改，再编辑关联；原话片段菜单提供关联证据。</p><label>当前方面关联<select id="a-link"></select></label><label>关系种类<select id="a-kind"><option value="explicit">明确对应</option><option value="partial">部分对应</option><option value="related">内容相关</option><option value="undetermined">暂未定</option><option value="outside">清单外</option></select></label><label>A关注条目<select id="a-item"></select></label><p id="a-item-text"></p><label>具体范围<textarea id="a-scope"></textarea></label><label>对应或清单外理由<textarea id="a-reason"></textarea></label><label>关联核对状态<select id="a-status"><option value="working">未核对</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label><p id="a-link-evidence"></p><button id="a-save" type="button">暂存这项对应</button><button id="a-remove" type="button">移除此关联</button></details>
<details id="editor-audit"><summary>修改记录（修改者与说明）</summary><label>修改者<input id="actor" autocomplete="off" value="本机使用者"></label><label>修改说明<input id="reason" autocomplete="off" value="修改分析结果"></label></details><button id="stage" type="button">暂存这条修改</button><button id="download" type="button" disabled>下载修改文件</button><p id="draft" role="status"></p><p id="message" role="alert"></p></section>
<details id="editor-themes"><summary>整理主题</summary><section><h2>主题定义与成员依据</h2><label>主题<select id="theme"></select></label><label>主题名称<input id="theme-label"></label><label>定义与边界<textarea id="theme-definition"></textarea></label><label>父主题（可多选）<select id="theme-parents" multiple size="3"></select></label><button id="theme-stage" type="button">暂存主题</button><label>当前方面加入此主题的依据<textarea id="member-reason"></textarea></label><button id="member-add" type="button">加入当前方面</button><button id="member-withdraw" type="button">撤回当前方面的此项归属</button><p id="members"></p><details><summary>全部保存主题定义</summary><div id="saved-themes"></div></details></section>
</details><details id="editor-relations"><summary>整理关注之间的联系</summary><section><h2>有范围的关系</h2><label>关系<select id="relation"></select></label><label>关系端点方面<select id="relation-facet"></select></label><label>关系类型<input id="relation-type"></label><label>此方面在联系中的作用<input id="relation-role"></label><button id="endpoint-add" type="button">添加方面端点</button><label>已选端点<select id="endpoints" size="3"></select></label><button id="endpoint-remove" type="button">移除所选端点</button><label>方向或无方向说明<input id="relation-direction"></label><label>具体作用范围<textarea id="relation-scope"></textarea></label><label>如何理解这项联系<textarea id="relation-reading"></textarea></label><label>歧义与未决说明<textarea id="relation-ambiguity"></textarea></label><p>采用当前原话证据；多个出处可在选择片段后追加。</p><button id="relation-evidence" type="button">追加当前证据</button><p id="relation-evidence-list"></p><label>关系核对状态<select id="relation-status"><option value="working">未核对</option><option value="needs_review">待核对</option><option value="confirmed">已核对分析</option><option value="withdrawn">撤回</option></select></label><button id="relation-stage" type="button">暂存这项联系</button><details><summary>全部保存关系与沿革（当前筛选的角色/范围见上方明细）</summary><div id="saved-relations"></div></details></section>
</details></details><details id="reading-history"><summary>完整解释、A原文与保存历史</summary><section><h2>全材料解释与沿革</h2><details><summary>展开全部保存解释与撤回/替换历史（不随上方筛选）</summary><h3>当前有效解释</h3><div id="saved"></div><details><summary>撤回和被替换解释（历史）</summary><div id="saved-archive"></div></details></details></section><section><h2>A工作参照</h2><p id="a-version"></p><details><summary>A条目原文与历史版本</summary><div id="a-items"></div></details></section><section><h2>保存历史</h2><div id="history"></div></section></details><script id="attention-data" type="application/json">''' + data + '</script><script id="attention-summary-data" type="application/json">' + saved + '</script><script id="attention-position-data" type="application/json">' + positions + '</script><script>' + map_script + '</script><script>' + position_script + '</script><script>' + views + '</script><script>' + script + '</script></body></html>'

    if session:
        context = json.dumps(session, ensure_ascii=True).replace('<', '\\u003c')
        page = page.replace("connect-src 'none'", "connect-src 'self'")
        if session.get('workbench_url'):
            url = html.escape(session['workbench_url'], quote=True)
            page = page.replace('<nav aria-label="结果页导航">', '<nav aria-label="结果页导航"><a href="' + url + '">返回工作台</a>', 1)
        page = page.replace('<script id="attention-data"', '<script id="attention-session" type="application/json">' + context + '</script><script id="attention-data"', 1)
    page = page.replace('修改后下载修改文件，回本机窗口保存，再重开查看。', '修改后点击“保存修改”。保存成功后更新当前结果。' if session else '这是静态导出页；可导出草稿，不能直接保存。请从桌面打开当前结果继续编辑。')
    page = page.replace('<button id="stage"', '<button id="save" type="button"' + ('' if session else ' disabled') + '>保存修改</button><button id="stage"')
    page = page.replace('下载修改文件</button>', '导出草稿</button>')
    page = page.replace('<button id="download" type="button" disabled>导出草稿</button>', '<details id="editor-export"><summary>导出草稿（可选）</summary><p>导出保留一份修改文件，不会保存到分析包。</p><button id="download" type="button" disabled>导出草稿</button></details>')
    css = Path(__file__).with_name('attention_web.css').read_text(encoding='utf-8')
    page = page.replace('</style><body>', css + '</style><body>', 1)
    return page
